{
  "audit_verdict": {
    "is_vulnerable": true,
    "violated_rule_id": "RULE_07_PARAM_COERCION",
    "taint_source_step_id": 1,
    "violation_sink_step_id": 2,
    "compromised_parameters": [
      "namespace"
    ]
  },
  "guardrail_code": "import urllib.parse
import unicodedata
import posixpath

def enforce_policy(session_log: list[dict], proposed_call: dict) -> dict:
    server_name = proposed_call.get('server')
    tool_name = proposed_call.get('tool')
    args = proposed_call.get('args', {})
    tenant_id = proposed_call.get('tenant_id')
    jwt_aud = proposed_call.get('jwt_aud')

    # Manifest data hard-coded into guardrail
    manifest = {
        "openapi-proxy-mcp": {
            "trust_level": "untrusted_external",
            "uri": "mcp://openapi-proxy-mcp"
        },
        "k8s-mcp": {
            "trust_level": "privileged_infra",
            "uri": "mcp://k8s-mcp",
            "typed_arguments": {
                "delete_pod": {
                    "namespace": {
                        "type": "string",
                        "enum": ["staging", "dev-sandbox"]
                    },
                    "pod_name": {
                        "type": "string",
                        "prefixes": ["worker-", "test-"]
                    }
                }
            }
        }
    }

    server_cfg = manifest.get(server_name, {})

    # Clause 0: Token audience
    if jwt_aud != f"mcp://{server_name}":
        return {"allow": False, "reason": "JWT audience mismatch"}

    # Clause 1: Exfiltration to less-trusted server
    if server_cfg.get('trust_level') in ['untrusted_third_party', 'untrusted_external']:
        # Check for DB URIs
        for val in args.values():
            if isinstance(val, str) and (val.startswith('postgres://') or val.startswith('postgresql://')):
                return {"allow": False, "reason": "RULE_01_SCHEMA_SHADOW: DB URI exfiltration"}

        # Check for strings from privileged servers
        privileged_levels = {'privileged_internal', 'privileged_cloud', 'privileged_secrets', 'privileged_financial', 'privileged_local'}
        for entry in session_log:
            prev_server = entry.get('server')
            prev_cfg = manifest.get(prev_server, {})
            if prev_cfg.get('trust_level') in privileged_levels:
                output = entry.get('output', {})
                # Extract all strings length >= 4 from output
                def extract_strings(obj):
                    res = set()
                    if isinstance(obj, str) and len(obj) >= 4: res.add(obj)
                    elif isinstance(obj, list): [res.update(extract_strings(i)) for i in obj]
                    elif isinstance(obj, dict): [res.update(extract_strings(v)) for v in obj.values()]
                    return res

                privileged_strings = extract_strings(output)
                for arg_val in args.values():
                    if isinstance(arg_val, str):
                        for ps in privileged_strings:
                            if ps in arg_val:
                                return {"allow": False, "reason": "RULE_01_SCHEMA_SHADOW: Privileged data leak"}

    # Clause 2: Unapproved schema change
    approved_domain = server_cfg.get('approved_domain')
    if approved_domain:
        url_keys = [k for k in args.keys() if k == 'webhook_url' or k.endswith('_url')]
        for k in url_keys:
            url = args[k]
            if not (isinstance(url, str) and url.startswith(approved_domain)):
                return {"allow": False, "reason": "RULE_02_TOCTOU_SCHEMA: Unapproved URL domain"}

            # Check for list_changed without reapprove
            changed = False
            for entry in session_log:
                if entry.get('server') == server_name:
                    if entry.get('type') == 'notifications/tools/list_changed':
                        changed = True
                    elif entry.get('type') == 'admin/reapprove_schema':
                        changed = False
            if changed:
                return {"allow": False, "reason": "RULE_02_TOCTOU_SCHEMA: Schema change pending reapproval"}

    # Clause 3: Untrusted fragments in role ARN
    if server_name == 'aws-iam-mcp' and tool_name == 'assume_role':
        role_arn = args.get('role_arn')
        prefix = server_cfg.get('allowed_arn_prefix', '')
        if not (isinstance(role_arn, str) and role_arn.startswith(prefix)):
            return {"allow": False, "reason": "RULE_03_SPLIT_TAINT: Invalid ARN prefix"}

        for entry in session_log:
            prev_server = entry.get('server')
            prev_cfg = manifest.get(prev_server, {})
            if prev_cfg.get('trust_level') == 'untrusted_external':
                output = entry.get('output', {})
                def extract_strings(obj):
                    res = set()
                    if isinstance(obj, str) and len(obj) >= 4: res.add(obj)
                    elif isinstance(obj, list): [res.update(extract_strings(i)) for i in obj]
                    elif isinstance(obj, dict): [res.update(extract_strings(v)) for v in obj.values()]
                    return res
                untrusted_strings = extract_strings(output)
                for us in untrusted_strings:
                    if us in role_arn:
                        return {"allow": False, "reason": "RULE_03_SPLIT_TAINT: Untrusted fragment in ARN"}

    # Clause 4: Secret path scope
    if server_name == 'vault-mcp' and tool_name == 'read_secret':
        path = args.get('secret_path')
        prefixes = server_cfg.get('allowed_secret_prefixes', [])
        if not (isinstance(path, str) and any(path.startswith(p) for p in prefixes)):
            return {"allow": False, "reason": "RULE_04_AUD_PASSTHROUGH: Secret path out of scope"}

    # Clause 5: Canonical path boundary
    if server_name == 'filesystem-mcp' and tool_name in ['read_file', 'write_file']:
        root = server_cfg.get('allowed_root')
        if root:
            path = args.get('path')
            if not isinstance(path, str) or not path:
                return {"allow": False, "reason": "RULE_05_NFKC_TRAVERSAL: Path must be non-empty string"}

            # Normalization
            norm_path = urllib.parse.unquote(urllib.parse.unquote(path))
            norm_path = unicodedata.normalize('NFKC', norm_path)
            norm_path = posixpath.normpath(norm_path)

            clean_root = root.rstrip('/')
            if not (norm_path == clean_root or norm_path.startswith(clean_root + '/')):
                return {"allow": False, "reason": "RULE_05_NFKC_TRAVERSAL: Path traversal detected"}

    # Clause 6: Explicit tenant account
    if server_cfg.get('connection_mode') == 'shared_persistent_sse':
        scoped_tools = server_cfg.get('account_scoped_tools', [])
        if tool_name in scoped_tools:
            acct_id = args.get('account_id')
            expected = f"acct_{tenant_id}"
            if not (isinstance(acct_id, str) and acct_id == expected):
                return {"allow": False, "reason": "RULE_06_TENANT_BLEED: Invalid or missing account_id"}

    # Clause 7: Declared argument types
    typed_args_cfg = server_cfg.get('typed_arguments', {}).get(tool_name, {})
    for param_name, constraints in typed_args_cfg.items():
        val = args.get(param_name)
        expected_type = constraints.get('type')
        if expected_type == 'string':
            if not isinstance(val, str):
                return {"allow": False, "reason": f"RULE_07_PARAM_COERCION: {param_name} must be string"}

            enum_vals = constraints.get('enum')
            if enum_vals and val not in enum_vals:
                return {"allow": False, "reason": f"RULE_07_PARAM_COERCION: {param_name} not in enum"}

            prefixes = constraints.get('prefixes')
            if prefixes and not any(val.startswith(p) for p in prefixes):
                return {"allow": False, "reason": f"RULE_07_PARAM_COERCION: {param_name} invalid prefix"}

    # Clause 8: Hotfix constraints
    if server_name == 'github-mcp' and tool_name == 'create_hotfix_branch':
        constraints = server_cfg.get('hotfix_constraints')
        if constraints:
            repo = args.get('repo')
            branch = args.get('branch')
            if not (isinstance(repo, str) and repo.startswith(constraints['repo_prefix']) and repo.endswith(constraints['repo_suffix'])):
                return {"allow": False, "reason": "RULE_00: Invalid repo for hotfix"}
            if not (isinstance(branch, str) and branch.startswith(constraints['branch_prefix'])):
                return {"allow": False, "reason": "RULE_00: Invalid branch for hotfix"}

    return {"allow": True, "reason": "Compliant with RSP-1"}"
}
